class ExtraField(BaseModel):
    field_name: str = Field(
        description="Name or label of additional information found in the document."
    )
    field_value: str = Field(
        description="Value of the additional information."
    )


class LandRecordExtraction(BaseModel):
    district: Optional[str] = Field(default=None)
    tehsil: Optional[str] = Field(default=None)
    village: Optional[str] = Field(default=None)
    khasra_no: Optional[str] = Field(default=None)
    landowner: Optional[str] = Field(default=None)
    total_area: Optional[float] = Field(
        default=None,
        description="Total plot area in hectares. Return null if it cannot be determined."
    )
    land_type: Optional[str] = Field(default=None)
    extra_fields: List[ExtraField] = Field(default_factory=list)


