@st.cache_data(show_spinner=False, ttl=86400)
def get_translation(text: str, target_lang: str) -> str:
    if not text or target_lang == "English":
        return text

    try:
        code = LANG_CODES.get(target_lang, "en")
        return GoogleTranslator(source="en", target=code).translate(text)
    except Exception:
        return text


def t(text: str) -> str:
    language = st.session_state.get("language", "English")
    return get_translation(text, language)


# =========================================================
# 4. PASSWORD SECURITY
# =========================================================

def hash_password(password: str, iterations: int = 310_000) -> str:
    """PBKDF2-SHA256 password hash with a unique random salt."""
    if not isinstance(password, str) or not password:
        raise ValueError("Password cannot be empty.")

    salt = secrets.token_bytes(16)
    digest = __import__("hashlib").pbkdf2_hmac(
        "sha256",
        password.encode("utf-8"),
        salt,
        iterations,
    )
    return f"pbkdf2_sha256${iterations}${salt.hex()}${digest.hex()}"


def verify_password(password: str, stored_hash: str) -> bool:
    """Verify modern PBKDF2 hashes and legacy SHA-256 hashes."""
    if not password or not stored_hash:
        return False

    try:
        parts = stored_hash.split("$")
        if len(parts) == 4 and parts[0] == "pbkdf2_sha256":
            iterations = int(parts[1])
            salt = bytes.fromhex(parts[2])
            expected = bytes.fromhex(parts[3])
            actual = __import__("hashlib").pbkdf2_hmac(
                "sha256",
                password.encode("utf-8"),
                salt,
                iterations,
            )
            return secrets.compare_digest(actual, expected)

        # Backward compatibility for databases created by the old app.
        if re.fullmatch(r"[0-9a-fA-F]{64}", stored_hash):
            legacy = __import__("hashlib").sha256(
                password.encode("utf-8")
            ).hexdigest()
            return secrets.compare_digest(legacy, stored_hash)

    except (ValueError, TypeError):
        return False

    return False


# =========================================================
# 5. DATABASE
# =========================================================

def get_connection() -> sqlite3.Connection:
    conn = sqlite3.connect(DB_FILE, timeout=15)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys = ON")
    conn.execute("PRAGMA busy_timeout = 15000")
    return conn


def column_exists(conn: sqlite3.Connection, table: str, column: str) -> bool:
    rows = conn.execute(f"PRAGMA table_info({table})").fetchall()
    return any(row["name"] == column for row in rows)


def init_db() -> None:
    conn = get_connection()
    try:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS users (
                username TEXT PRIMARY KEY COLLATE NOCASE,
                password_hash TEXT NOT NULL,
                full_name TEXT NOT NULL,
                role TEXT NOT NULL CHECK(role IN ('admin', 'user')),
                created_at TEXT NOT NULL
            )
            """
        )

        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS land_records (
                record_id TEXT PRIMARY KEY,
                district TEXT NOT NULL,
                tehsil TEXT NOT NULL,
                village TEXT NOT NULL,
                khasra_no TEXT NOT NULL,
                plot_area REAL NOT NULL CHECK(plot_area > 0),
                landowner TEXT NOT NULL,
                land_type TEXT NOT NULL,
                latitude REAL NOT NULL CHECK(latitude >= -90 AND latitude <= 90),
                longitude REAL NOT NULL CHECK(longitude >= -180 AND longitude <= 180),
                input_mode TEXT NOT NULL,
                status TEXT NOT NULL,
                timestamp TEXT NOT NULL,
                created_by TEXT NOT NULL COLLATE NOCASE,
                extra_data TEXT NOT NULL DEFAULT '{}',
                image_paths TEXT NOT NULL DEFAULT '[]'
            )
            """
        )

        # Migrate columns from the previous version if this is an old DB.
        if not column_exists(conn, "users", "created_at"):
            conn.execute(
                "ALTER TABLE users ADD COLUMN created_at TEXT"
            )
            conn.execute(
                "UPDATE users SET created_at = ? WHERE created_at IS NULL",
                (utc_now(),),
            )

        if not column_exists(conn, "land_records", "extra_data"):
            conn.execute(
                "ALTER TABLE land_records ADD COLUMN extra_data TEXT DEFAULT '{}'"
            )

        if not column_exists(conn, "land_records", "image_paths"):
            conn.execute(
                "ALTER TABLE land_records ADD COLUMN image_paths TEXT DEFAULT '[]'"
            )

        # Helpful index for ownership queries.
        conn.execute(
            """
            CREATE INDEX IF NOT EXISTS idx_land_records_created_by
            ON land_records(created_by)
            """
        )

        # Case-insensitive logical uniqueness for parcel identity.
        # Existing duplicate data is handled gracefully rather than crashing startup.
        try:
            conn.execute(
                """
                CREATE UNIQUE INDEX IF NOT EXISTS uq_land_parcel
                ON land_records(
                    district COLLATE NOCASE,
                    tehsil COLLATE NOCASE,
                    village COLLATE NOCASE,
                    khasra_no COLLATE NOCASE
                )
                """
            )
        except sqlite3.IntegrityError:
            # An old database may already contain duplicates.
            # The application still performs duplicate checks before writes.
            pass

        conn.commit()
    finally:
        conn.close()


def utc_now() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S UTC")


def normalize_text(value: object) -> str:
    return " ".join(str(value or "").strip().split())


def validate_registration(
    username: str,
    password: str,
    full_name: str,
) -> Optional[str]:
    username = normalize_text(username)
    full_name = normalize_text(full_name)

    if not username or not full_name or not password:
        return "Please fill in all required fields."

    if len(username) < 3 or len(username) > 50:
        return "Username must be between 3 and 50 characters."

    if not re.fullmatch(r"[A-Za-z0-9_.-]+", username):
        return "Username may contain only letters, numbers, dot, underscore, and hyphen."

    if len(full_name) < 2 or len(full_name) > 100:
        return "Please enter a valid full name."

    if len(password) < 8:
        return "Password must be at least 8 characters."

    return None


def user_count() -> int:
    conn = get_connection()
    try:
        return int(conn.execute("SELECT COUNT(*) FROM users").fetchone()[0])
    finally:
        conn.close()


def register_user(
    username: str,
    password: str,
    full_name: str,
    role: str,
) -> tuple[bool, str]:
    username = normalize_text(username)
    full_name = normalize_text(full_name)

    error = validate_registration(username, password, full_name)
    if error:
        return False, error

    if role not in {"admin", "user"}:
        return False, "Invalid role."

    conn = get_connection()
    try:
        conn.execute(
            """
            INSERT INTO users(username, password_hash, full_name, role, created_at)
            VALUES (?, ?, ?, ?, ?)
            """,
            (
                username,
                hash_password(password),
                full_name,
                role,
                utc_now(),
            ),
        )
        conn.commit()
        return True, "Account created successfully."
    except sqlite3.IntegrityError:
        return False, "Username already exists."
    finally:
        conn.close()


def authenticate_user(username: str, password: str):
    username = normalize_text(username)

    if not username or not password:
        return None

    conn = get_connection()
    try:
        row = conn.execute(
            """
            SELECT username, password_hash, full_name, role
            FROM users
            WHERE username = ? COLLATE NOCASE
            """,
            (username,),
        ).fetchone()

        if row is None or not verify_password(password, row["password_hash"]):
            return None

        # Upgrade legacy SHA-256 hashes after a successful login.
        if not row["password_hash"].startswith("pbkdf2_sha256$"):
            conn.execute(
                """
                UPDATE users
                SET password_hash = ?
                WHERE username = ? COLLATE NOCASE
                """,
                (hash_password(password), row["username"]),
            )
            conn.commit()

        return (
            row["username"],
            row["full_name"],
            row["role"],
        )
    finally:
        conn.close()


def parcel_exists(
    district: str,
    tehsil: str,
    village: str,
    khasra_no: str,
    exclude_record_id: Optional[str] = None,
) -> bool:
    district = normalize_text(district)
    tehsil = normalize_text(tehsil)
    village = normalize_text(village)
    khasra_no = normalize_text(khasra_no)

    conn = get_connection()
    try:
        query = """
            SELECT 1
            FROM land_records
            WHERE district = ? COLLATE NOCASE
              AND tehsil = ? COLLATE NOCASE
              AND village = ? COLLATE NOCASE
              AND khasra_no = ? COLLATE NOCASE
        """
        params = [district, tehsil, village, khasra_no]

        if exclude_record_id:
            query += " AND record_id <> ?"
            params.append(exclude_record_id)

        query += " LIMIT 1"

        return conn.execute(query, params).fetchone() is not None
    finally:
        conn.close()


def insert_record(record_tuple: tuple) -> None:
    conn = get_connection()
    try:
        conn.execute(
            """
            INSERT INTO land_records(
                record_id, district, tehsil, village, khasra_no,
                plot_area, landowner, land_type, latitude, longitude,
                input_mode, status, timestamp, created_by,
                extra_data, image_paths
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            record_tuple,
        )
        conn.commit()
    finally:
        conn.close()


def update_record(
    record_id: str,
    district: str,
    tehsil: str,
    village: str,
    khasra_no: str,
    plot_area: float,
    landowner: str,
    land_type: str,
    extra_data_json: str,
) -> None:
    conn = get_connection()
    try:
        conn.execute(
            """
            UPDATE land_records
            SET district = ?,
                tehsil = ?,
                village = ?,
                khasra_no = ?,
                plot_area = ?,
                landowner = ?,
                land_type = ?,
                extra_data = ?
            WHERE record_id = ?
            """,
            (
                normalize_text(district),
                normalize_text(tehsil),
                normalize_text(village),
                normalize_text(khasra_no),
                float(plot_area),
                normalize_text(landowner),
                land_type,
                extra_data_json,
                record_id,
            ),
        )
        conn.commit()
    finally:
        conn.close()


def fetch_records_by_role(username: str, role: str) -> pd.DataFrame:
    columns = [
        "record_id", "district", "tehsil", "village", "khasra_no",
        "plot_area", "landowner", "land_type", "latitude", "longitude",
        "input_mode", "status", "timestamp", "created_by",
        "extra_data", "image_paths",
    ]

    conn = get_connection()
    try:
        if role == "admin":
            query = f"""
                SELECT {", ".join(columns)}
                FROM land_records
                ORDER BY timestamp DESC
            """
            df = pd.read_sql_query(query, conn)
        else:
            query = f"""
                SELECT {", ".join(columns)}
                FROM land_records
                WHERE created_by = ? COLLATE NOCASE
                ORDER BY timestamp DESC
            """
            df = pd.read_sql_query(query, conn, params=(username,))
    finally:
        conn.close()

    if not df.empty:
        df.columns = [
            "Record ID", "District", "Tehsil", "Village",
            "Khasra / Survey No", "Plot Area (Ha)", "Landowner",
            "Classification", "Latitude", "Longitude", "Input Mode",
            "Status", "Timestamp", "Created By", "Extra Data", "Image Paths",
        ]

    return df


# =========================================================
# 6. DOCUMENT VALIDATION / STORAGE
# =========================================================

def safe_original_name(filename: str) -> str:
    name = Path(filename or "document").name
    stem = re.sub(r"[^A-Za-z0-9._-]", "_", Path(name).stem)[:80]
    suffix = Path(name).suffix.lower()

    if suffix not in ALLOWED_EXTENSIONS:
        suffix = ".jpg"

    return f"{stem or 'document'}{suffix}"


def validate_uploaded_image(uploaded_file) -> None:
    if uploaded_file is None:
        raise ValueError("No file was provided.")

    if uploaded_file.size > MAX_UPLOAD_BYTES:
        raise ValueError(
            f"{uploaded_file.name} exceeds the {MAX_UPLOAD_MB} MB file-size limit."
        )

    suffix = Path(uploaded_file.name).suffix.lower()
    if suffix not in ALLOWED_EXTENSIONS:
        raise ValueError(f"Unsupported file type: {uploaded_file.name}")

    mime = getattr(uploaded_file, "type", "")
    if mime and mime not in ALLOWED_MIME_TYPES:
        raise ValueError(f"Unsupported image MIME type: {mime}")

    uploaded_file.seek(0)
    try:
        with Image.open(uploaded_file) as image:
            image.verify()
    except (UnidentifiedImageError, OSError) as exc:
        raise ValueError(f"{uploaded_file.name} is not a valid image.") from exc
    finally:
        uploaded_file.seek(0)


def save_uploaded_files(uploaded_files, record_id: str) -> list[str]:
    saved_paths: list[str] = []

    try:
        for index, uploaded_file in enumerate(uploaded_files):
            validate_uploaded_image(uploaded_file)

            original = safe_original_name(uploaded_file.name)
            unique_name = (
                f"{record_id}_{index + 1}_{uuid.uuid4().hex}{Path(original).suffix}"
            )
            destination = UPLOAD_DIR / unique_name

            uploaded_file.seek(0)
            data = uploaded_file.getvalue()

            if len(data) > MAX_UPLOAD_BYTES:
                raise ValueError(f"{uploaded_file.name} is too large.")

            destination.write_bytes(data)
            saved_paths.append(str(destination))

        return saved_paths

    except Exception:
        # Roll back files if a later file fails.
        for path in saved_paths:
            try:
                Path(path).unlink(missing_ok=True)
            except OSError:
                pass
        raise


def delete_saved_files(paths: list[str]) -> None:
    for path in paths:
        try:
            file_path = Path(path).resolve()
            upload_root = UPLOAD_DIR.resolve()

            # Only delete files inside our upload directory.
            if upload_root in file_path.parents:
                file_path.unlink(missing_ok=True)
        except (OSError, RuntimeError):
            pass


# =========================================================
# 7. AI EXTRACTION
# =========================================================

def extract_land_record_data(uploaded_files) -> LandRecordExtraction:
    if genai is None or types is None:
        raise RuntimeError(
            "The google-genai package is not installed. "
            "Install it with: pip install google-genai"
        )

    if not GEMINI_API_KEY:
        raise RuntimeError(
            "Gemini API key is not configured. "
            "Set GEMINI_API_KEY in Streamlit secrets or an environment variable."
        )

    images = []
    for uploaded_file in uploaded_files:
        validate_uploaded_image(uploaded_file)
        uploaded_file.seek(0)
        image = Image.open(uploaded_file).convert("RGB")
        images.append(image)

    prompt = """
    Analyze the provided land-record document image(s).

    Extract only information that is actually visible or strongly supported
    by the document. Do not invent values.

    If multiple images belong to the same land record, merge their information.
    If a field cannot be determined, return null.

    For total_area, return the value in hectares when the document explicitly
    provides hectares or when a clear unit conversion is possible. If the unit
    is unclear, return null rather than guessing.

    For land_type, use one of:
    Agricultural, Non-Agricultural, Commercial, Forest
    when supported. Otherwise return null.

    Put other useful labelled fields into extra_fields.
    """

    client = genai.Client(api_key=GEMINI_API_KEY)

    # Current Google GenAI SDK supports Pydantic response_schema for
    # generate_content. This is intentionally kept compatible with the
    # existing app architecture.
    response = client.models.generate_content(
        model=GEMINI_MODEL,
        contents=[prompt, *images],
        config=types.GenerateContentConfig(
            response_mime_type="application/json",
            response_schema=LandRecordExtraction,
            temperature=0.1,
        ),
    )

    if getattr(response, "parsed", None) is not None:
        parsed = response.parsed
        if isinstance(parsed, LandRecordExtraction):
            return parsed
        return LandRecordExtraction.model_validate(parsed)

    response_text = getattr(response, "text", None)
    if not response_text:
        raise RuntimeError("Gemini returned an empty response.")

    return LandRecordExtraction.model_validate_json(response_text)


def sanitize_extracted_data(data: LandRecordExtraction) -> LandRecordExtraction:
    if data.total_area is not None:
        if not math.isfinite(float(data.total_area)) or data.total_area <= 0:
            data.total_area = None

    if data.land_type not in LAND_TYPES:
        data.land_type = None

    return data


