def fetch_public_statistics() -> dict:
    """Return safe aggregate statistics for the public landing page."""
    stats = {
        "records": 0,
        "villages": 0,
        "districts": 0,
        "users": 0,
    }
    conn = get_connection()
    try:
        row = conn.execute(
            """
            SELECT
                COUNT(*) AS records,
                COUNT(DISTINCT Village) AS villages,
                COUNT(DISTINCT District) AS districts
            FROM land_records
            """
        ).fetchone()
        if row:
            stats["records"] = int(row["records"] or 0)
            stats["villages"] = int(row["villages"] or 0)
            stats["districts"] = int(row["districts"] or 0)
    except sqlite3.Error:
        pass
    finally:
        conn.close()

    stats["users"] = user_count()
    return stats


