def render_auth_screen() -> None:
    top_left, top_center, top_right = st.columns([1, 2, 1])
    with top_center:
        st.markdown(_render_logo(180), unsafe_allow_html=True)

    if st.button("← Back to Home", use_container_width=False):
        st.session_state.page = "home"
        st.rerun()

    st.markdown(
        f"""
        <div class="main-header" style="text-align:center;">
            <h1>{t("PRITHVI")}</h1>
            <p>
                {t("Portal for Rural Indian Terrain, Holding, and Village Information")}
            </p>
        </div>
        """,
        unsafe_allow_html=True,
    )

    if user_count() == 0:
        st.info(
            t(
                "No accounts exist yet. Create the first account below; "
                "the first account is assigned the administrator role."
            )
        )

    _, login_col, _ = st.columns([1, 1.5, 1])

    with login_col:
        mode_hint = st.session_state.get("auth_mode", "login")
        if mode_hint == "register":
            st.info("Select the **Register New Account** tab below to create your account.")
        else:
            st.info("Use the login tab to access your PRITHVI workspace, or register a new account.")
        tab_login, tab_register = st.tabs(
            [t("🔐 Login"), t("📝 Register New Account")]
        )

        with tab_login:
            username_input = st.text_input(
                t("Username"),
                key="login_username",
            )
            password_input = st.text_input(
                t("Password"),
                type="password",
                key="login_password",
            )

            if st.button(t("Log In"), use_container_width=True):
                user = authenticate_user(username_input, password_input)

                if user:
                    (
                        st.session_state.authenticated,
                        st.session_state.username,
                        st.session_state.full_name,
                        st.session_state.role,
                    ) = (True, user[0], user[1], user[2])
                    st.session_state.login_error = None
                    st.rerun()
                else:
                    st.error(t("Invalid username or password."))

        with tab_register:
            reg_name = st.text_input(
                t("Full Name"),
                key="register_name",
            )
            reg_user = st.text_input(
                t("New Username"),
                key="register_username",
            )
            reg_pass = st.text_input(
                t("New Password"),
                type="password",
                key="register_password",
            )
            reg_pass_confirm = st.text_input(
                t("Confirm Password"),
                type="password",
                key="register_password_confirm",
            )

            if st.button(t("Create Account"), use_container_width=True):
                if reg_pass != reg_pass_confirm:
                    st.error(t("Passwords do not match."))
                else:
                    first_account = user_count() == 0
                    role = "admin" if first_account else "user"

                    success, message = register_user(
                        reg_user,
                        reg_pass,
                        reg_name,
                        role,
                    )

                    if success:
                        if first_account:
                            st.success(
                                t(
                                    "Administrator account created. "
                                    "Please log in."
                                )
                            )
                        else:
                            st.success(t("Account created. Please log in."))
                    else:
                        st.error(t(message))

    st.stop()


