# 11. UPLOAD / AI ENTRY TAB
# =========================================================

def render_entry_tab() -> None:
    st.subheader(t("📸 Document Upload & AI Assisted Entry"))
    st.caption(
        t(
            "Upload one or more land documents, extract the visible fields "
            "with AI, then verify everything before saving."
        )
    )

    uploaded_files = st.file_uploader(
        t("Upload Scanned Land Record (PNG, JPG, JPEG)"),
        type=["png", "jpg", "jpeg"],
        accept_multiple_files=True,
        help=t(f"Maximum {MAX_UPLOAD_MB} MB per image."),
    )

    if not uploaded_files:
        st.warning(t("⚠️ Upload at least one document image to continue."))
    else:
        if st.button(
            t("🧠 Extract Data using AI"),
            use_container_width=True,
            type="primary",
        ):
            try:
                with st.spinner(
                    t("Analyzing documents using Google Gemini...")
                ):
                    extracted = extract_land_record_data(uploaded_files)
                    st.session_state.ai_extracted_data = sanitize_extracted_data(
                        extracted
                    )

                st.success(
                    t(
                        "✅ AI extraction complete. "
                        "Review every field before saving."
                    )
                )
            except Exception as exc:
                st.session_state.ai_extracted_data = None
                st.error(f"{t('AI extraction failed:')} {exc}")

    st.divider()

    st.markdown(t("### 📍 Pinpoint Land Parcel Location"))

    default_lat = 23.0225
    default_lon = 72.5714

    m_picker = folium.Map(
        location=[default_lat, default_lon],
        zoom_start=8,
        tiles=None,
    )

    folium.TileLayer(
        tiles="https://mt1.google.com/vt/lyrs=y&x={x}&y={y}&z={z}",
        attr="Google",
        name="Satellite View",
        overlay=False,
        control=True,
    ).add_to(m_picker)

    folium.TileLayer(
        "OpenStreetMap",
        name="Street View",
    ).add_to(m_picker)

    folium.LayerControl().add_to(m_picker)
    Fullscreen(position="topright").add_to(m_picker)
    m_picker.add_child(folium.LatLngPopup())

    map_data = st_folium(
        m_picker,
        height=400,
        use_container_width=True,
        key="map_picker",
    )

    clicked = map_data.get("last_clicked") if map_data else None
    selected_lat = (
        float(clicked["lat"])
        if clicked and "lat" in clicked
        else default_lat
    )
    selected_lon = (
        float(clicked["lng"])
        if clicked and "lng" in clicked
        else default_lon
    )

    extracted = (
        st.session_state.ai_extracted_data
        or LandRecordExtraction()
    )

    st.markdown(t("### 📝 Verify & Complete Details"))
    st.info(
        t(
            "AI output is not authoritative. Verify the document and correct "
            "any extracted value before saving."
        )
    )

    with st.form("unified_entry_form"):
        col1, col2, col3 = st.columns(3)

        with col1:
            district = st.text_input(
                f"{t('District')} *",
                value=extracted.district or "",
            )

            land_type_default = (
                extracted.land_type
                if extracted.land_type in LAND_TYPES
                else LAND_TYPES[0]
            )

            land_type = st.selectbox(
                t("Land Classification"),
                LAND_TYPES,
                index=LAND_TYPES.index(land_type_default),
                format_func=lambda x: t(x),
            )

            latitude = st.number_input(
                t("📍 Latitude"),
                min_value=-90.0,
                max_value=90.0,
                value=max(-90.0, min(90.0, selected_lat)),
                format="%.6f",
            )

        with col2:
            tehsil = st.text_input(
                f"{t('Tehsil / Taluka')} *",
                value=extracted.tehsil or "",
            )

            khasra_no = st.text_input(
                f"{t('Khasra / Survey No.')} *",
                value=extracted.khasra_no or "",
            )

            longitude = st.number_input(
                t("📍 Longitude"),
                min_value=-180.0,
                max_value=180.0,
                value=max(-180.0, min(180.0, selected_lon)),
                format="%.6f",
            )

        with col3:
            village = st.text_input(
                f"{t('Village')} *",
                value=extracted.village or "",
            )

            owner_name = st.text_input(
                f"{t('Landowner Name(s)')} *",
                value=extracted.landowner or "",
            )

            extracted_area = (
                float(extracted.total_area)
                if extracted.total_area is not None
                and math.isfinite(float(extracted.total_area))
                and extracted.total_area > 0
                else 0.0
            )

            total_area = st.number_input(
                f"{t('Total Plot Area (Hectares)')} *",
                min_value=0.0,
                step=0.01,
                value=extracted_area,
            )

        extra_list = []

        if extracted.extra_fields:
            st.markdown(t("##### ✨ AI Identified Extra Fields"))

            for idx, extra in enumerate(extracted.extra_fields):
                field_name = normalize_text(extra.field_name)

                if not field_name:
                    field_name = f"Extra Field {idx + 1}"

                val = st.text_input(
                    field_name,
                    value=extra.field_value or "",
                    key=f"extra_form_{idx}",
                )

                extra_list.append(
                    {
                        "name": field_name,
                        "value": val,
                    }
                )

        submit_btn = st.form_submit_button(
            t("✅ Validate & Save to Database"),
            use_container_width=True,
        )

    if not submit_btn:
        return

    if not uploaded_files:
        st.error(t("Please upload at least one source document."))
        return

    district = normalize_text(district)
    tehsil = normalize_text(tehsil)
    village = normalize_text(village)
    khasra_no = normalize_text(khasra_no)
    owner_name = normalize_text(owner_name)

    required = {
        t("District"): district,
        t("Tehsil / Taluka"): tehsil,
        t("Village"): village,
        t("Khasra / Survey No."): khasra_no,
        t("Landowner Name(s)"): owner_name,
    }

    missing_fields = [
        label for label, value in required.items() if not value
    ]

    if total_area <= 0:
        missing_fields.append(t("Total Plot Area (Hectares)"))

    if missing_fields:
        st.error(
            t("❌ Please fill in: ")
            + ", ".join(missing_fields)
        )
        return

    if not (-90 <= latitude <= 90):
        st.error(t("Latitude must be between -90 and 90."))
        return

    if not (-180 <= longitude <= 180):
        st.error(t("Longitude must be between -180 and 180."))
        return

    if parcel_exists(district, tehsil, village, khasra_no):
        st.error(
            f"{t('⚠️ Duplicate Error: A record already exists for')} "
            f"{khasra_no} {t('in')} {village}, {tehsil}, {district}."
        )
        return

    record_id = f"REC-{uuid.uuid4().hex[:12].upper()}"
    timestamp = utc_now()

    saved_image_paths: list[str] = []

    try:
        saved_image_paths = save_uploaded_files(
            uploaded_files,
            record_id,
        )

        extra_data_json = (
            json.dumps(
                extra_list,
                ensure_ascii=False,
            )
            if extra_list
            else "{}"
        )

        insert_record(
            (
                record_id,
                district,
                tehsil,
                village,
                khasra_no,
                float(total_area),
                owner_name,
                land_type,
                float(latitude),
                float(longitude),
                "AI Merged & Verified",
                "Validated",
                timestamp,
                st.session_state.username,
                extra_data_json,
                json.dumps(saved_image_paths),
            )
        )

    except sqlite3.IntegrityError:
        delete_saved_files(saved_image_paths)
        st.error(
            t(
                "The record could not be saved because the parcel already "
                "exists. Please refresh and try again."
            )
        )
        return

    except Exception as exc:
        delete_saved_files(saved_image_paths)
        st.error(f"{t('Could not save the record:')} {exc}")
        return

    st.session_state.ai_extracted_data = None
    st.success(
        f"{t('🎉 Record & source documents saved successfully!')} "
        f"({record_id})"
    )
    st.balloons()


