def parse_extra_data(value: object) -> list[dict]:
    if value is None or pd.isna(value):
        return []

    raw = str(value).strip()

    if not raw or raw == "{}":
        return []

    try:
        parsed = json.loads(raw)
    except (TypeError, json.JSONDecodeError):
        return []

    if not isinstance(parsed, list):
        return []

    clean = []

    for item in parsed:
        if isinstance(item, dict):
            clean.append(
                {
                    "name": str(item.get("name", "Unknown Field")),
                    "value": str(item.get("value", "")),
                }
            )

    return clean


def parse_image_paths(value: object) -> list[str]:
    if value is None or pd.isna(value):
        return []

    raw = str(value).strip()

    if not raw or raw == "[]":
        return []

    try:
        parsed = json.loads(raw)
    except (TypeError, json.JSONDecodeError):
        return []

    if not isinstance(parsed, list):
        return []

    return [
        str(path)
        for path in parsed
        if isinstance(path, str) and path.strip()
    ]


def user_can_edit_record(record_owner: str) -> bool:
    return (
        st.session_state.role == "admin"
        or str(record_owner).lower()
        == str(st.session_state.username).lower()
    )


def render_database_tab() -> None:
    if st.session_state.role == "admin":
        st.subheader(t("📊 Central Land Records Registry (Admin View)"))
    else:
        st.subheader(
            f"{t('📊 My Land Records')} "
            f"({st.session_state.full_name})"
        )

    df = fetch_records_by_role(
        st.session_state.username,
        st.session_state.role,
    )

    if df.empty:
        st.warning(t("⚠️ No records found."))
        return

    c1, c2, c3, c4 = st.columns(4)

    with c1:
        st.metric(t("Total Records"), len(df))

    with c2:
        total_area_sum = pd.to_numeric(
            df["Plot Area (Ha)"],
            errors="coerce",
        ).fillna(0).sum()
        st.metric(
            t("Total Area"),
            f"{total_area_sum:.2f} Ha",
        )

    with c3:
        st.metric(
            t("Districts"),
            df["District"].nunique(),
        )

    with c4:
        st.metric(
            t("Access Mode"),
            t("All Records")
            if st.session_state.role == "admin"
            else t("Personal Records"),
        )

    st.divider()

    display_columns = [
        "Record ID",
        "District",
        "Tehsil",
        "Village",
        "Khasra / Survey No",
        "Plot Area (Ha)",
        "Landowner",
        "Classification",
        "Input Mode",
        "Status",
        "Timestamp",
        "Created By",
    ]

    st.markdown(t("### 🗃️ Parcel Records Directory"))
    st.dataframe(
        df[display_columns],
        use_container_width=True,
        hide_index=True,
    )

    st.divider()

    st.markdown(t("### 🔍 View / Edit Record Details"))

    options = [
        "-- Select a Record --"
    ] + [
        (
            f"{row['Record ID']} - "
            f"Khasra {row['Khasra / Survey No']} "
            f"({row['Village']})"
        )
        for _, row in df.iterrows()
    ]

    selected_option = st.selectbox(
        t("Select a Record to Inspect:"),
        options,
    )

    if selected_option == "-- Select a Record --":
        return

    selected_record_id = selected_option.split(" - ", 1)[0]

    matching = df[df["Record ID"] == selected_record_id]

    if matching.empty:
        st.error(t("Selected record could not be found."))
        return

    current_data = matching.iloc[0]

    st.markdown(
        '<div class="detail-card">',
        unsafe_allow_html=True,
    )

    st.markdown(
        f"#### 📄 {t('Record Details:')} "
        f"`{current_data['Record ID']}`"
    )

    v_col1, v_col2, v_col3 = st.columns(3)

    with v_col1:
        st.write(
            f"**{t('District')}:** {current_data['District']}"
        )
        st.write(
            f"**{t('Tehsil / Taluka')}:** {current_data['Tehsil']}"
        )
        st.write(
            f"**{t('Village')}:** {current_data['Village']}"
        )

    with v_col2:
        st.write(
            f"**{t('Khasra / Survey No.')}:** "
            f"{current_data['Khasra / Survey No']}"
        )
        st.write(
            f"**{t('Total Area')}:** "
            f"{current_data['Plot Area (Ha)']} Ha"
        )
        st.write(
            f"**{t('Land Classification')}:** "
            f"{current_data['Classification']}"
        )

    with v_col3:
        st.write(
            f"**{t('Landowner Name(s)')}:** "
            f"{current_data['Landowner']}"
        )
        st.write(
            f"**{t('Created By')}:** "
            f"{current_data['Created By']}"
        )
        st.write(
            f"**{t('Status')}:** "
            f"{current_data['Status']}"
        )

    parsed_extra_data = parse_extra_data(
        current_data["Extra Data"]
    )

    if parsed_extra_data:
        st.markdown(
            t("##### ✨ AI Extracted Extra Information")
        )

        for item in parsed_extra_data:
            st.write(
                f"🔸 **{item['name']}:** {item['value']}"
            )

    image_paths = parse_image_paths(
        current_data["Image Paths"]
    )

    if image_paths:
        st.markdown(
            t("##### 📎 Attached Source Documents")
        )

        valid_images = []

        for path in image_paths:
            try:
                resolved = Path(path).resolve()
                upload_root = UPLOAD_DIR.resolve()

                if upload_root in resolved.parents and resolved.is_file():
                    valid_images.append(resolved)
            except (OSError, RuntimeError):
                continue

        if valid_images:
            img_cols = st.columns(
                min(len(valid_images), 3)
            )

            for index, path in enumerate(valid_images):
                img_cols[index % len(img_cols)].image(
                    str(path),
                    use_container_width=True,
                    caption=path.name,
                )
        else:
            st.warning(
                t("Source image files are missing from disk.")
            )

    st.markdown(
        "</div>",
        unsafe_allow_html=True,
    )

    if not user_can_edit_record(current_data["Created By"]):
        st.info(
            t(
                "You can view this record, but only its owner or an "
                "administrator can edit it."
            )
        )
        return

    with st.expander(
        f"{t('✏️ Correct / Update details for')} "
        f"{selected_record_id}"
    ):
        with st.form(
            f"edit_form_{selected_record_id}"
        ):
            e_col1, e_col2, e_col3 = st.columns(3)

            with e_col1:
                edit_dist = st.text_input(
                    t("District"),
                    value=str(current_data["District"]),
                )
                edit_khasra = st.text_input(
                    t("Khasra / Survey No."),
                    value=str(
                        current_data["Khasra / Survey No"]
                    ),
                )

            with e_col2:
                edit_tehs = st.text_input(
                    t("Tehsil / Taluka"),
                    value=str(current_data["Tehsil"]),
                )

                try:
                    edit_area_value = float(
                        current_data["Plot Area (Ha)"]
                    )
                except (TypeError, ValueError):
                    edit_area_value = 0.01

                edit_area = st.number_input(
                    t("Total Plot Area (Hectares)"),
                    min_value=0.01,
                    value=max(0.01, edit_area_value),
                    step=0.01,
                )

            with e_col3:
                edit_vill = st.text_input(
                    t("Village"),
                    value=str(current_data["Village"]),
                )
                edit_owner = st.text_input(
                    t("Landowner Name(s)"),
                    value=str(current_data["Landowner"]),
                )

            current_type = str(
                current_data["Classification"]
            )

            type_index = (
                LAND_TYPES.index(current_type)
                if current_type in LAND_TYPES
                else 0
            )

            edit_type = st.selectbox(
                t("Land Classification"),
                LAND_TYPES,
                index=type_index,
                format_func=lambda x: t(x),
            )

            edited_extra_values = {}

            if parsed_extra_data:
                st.markdown(
                    t("##### ✏️ Edit Extra AI Fields")
                )

                for i, item in enumerate(parsed_extra_data):
                    field_name = normalize_text(
                        item.get("name", f"Unknown_{i}")
                    ) or f"Unknown_{i}"

                    field_val = item.get("value", "")

                    edited_extra_values[field_name] = st.text_input(
                        field_name,
                        value=field_val,
                        key=f"edit_extra_{selected_record_id}_{i}",
                    )

            update_btn = st.form_submit_button(
                t("💾 Save Corrections"),
                use_container_width=True,
            )

        if not update_btn:
            return

        edit_dist = normalize_text(edit_dist)
        edit_tehs = normalize_text(edit_tehs)
        edit_vill = normalize_text(edit_vill)
        edit_khasra = normalize_text(edit_khasra)
        edit_owner = normalize_text(edit_owner)

        missing = []

        for label, value in [
            (t("District"), edit_dist),
            (t("Tehsil / Taluka"), edit_tehs),
            (t("Village"), edit_vill),
            (t("Khasra / Survey No."), edit_khasra),
            (t("Landowner Name(s)"), edit_owner),
        ]:
            if not value:
                missing.append(label)

        if edit_area <= 0:
            missing.append(
                t("Total Plot Area (Hectares)")
            )

        if missing:
            st.error(
                t("Please fill in: ")
                + ", ".join(missing)
            )
            return

        if parcel_exists(
            edit_dist,
            edit_tehs,
            edit_vill,
            edit_khasra,
            exclude_record_id=selected_record_id,
        ):
            st.error(
                t(
                    "⚠️ Cannot save edits: another record already "
                    "uses this District + Tehsil + Village + Khasra combination."
                )
            )
            return

        new_extra_list = [
            {"name": name, "value": value}
            for name, value in edited_extra_values.items()
        ]

        try:
            update_record(
                selected_record_id,
                edit_dist,
                edit_tehs,
                edit_vill,
                edit_khasra,
                edit_area,
                edit_owner,
                edit_type,
                (
                    json.dumps(
                        new_extra_list,
                        ensure_ascii=False,
                    )
                    if new_extra_list
                    else "{}"
                ),
            )
        except sqlite3.IntegrityError:
            st.error(
                t(
                    "The update was rejected because it would create "
                    "a duplicate parcel record."
                )
            )
            return
        except Exception as exc:
            st.error(f"{t('Update failed:')} {exc}")
            return

        st.success(t("Record updated successfully!"))
        st.rerun()


