def render_gis_tab() -> None:
    st.subheader(
        t("🗺️ Geographic Information System (GIS) Viewer")
    )
    st.caption(
        t(
            "The displayed square is an approximate visualization around "
            "the stored point, not an official cadastral boundary."
        )
    )

    df = fetch_records_by_role(
        st.session_state.username,
        st.session_state.role,
    )

    if df.empty:
        st.warning(t("No land records available to map."))
        return

    df["Latitude"] = pd.to_numeric(
        df["Latitude"],
        errors="coerce",
    )
    df["Longitude"] = pd.to_numeric(
        df["Longitude"],
        errors="coerce",
    )

    df_mapped = df.dropna(
        subset=["Latitude", "Longitude"]
    ).copy()

    df_mapped = df_mapped[
        df_mapped["Latitude"].between(-90, 90)
        & df_mapped["Longitude"].between(-180, 180)
    ]

    if df_mapped.empty:
        st.warning(
            t("Existing records do not have valid GIS coordinates.")
        )
        return

    center_lat = float(
        df_mapped["Latitude"].mean()
    )
    center_lon = float(
        df_mapped["Longitude"].mean()
    )

    m_gis = folium.Map(
        location=[center_lat, center_lon],
        zoom_start=6,
        tiles=None,
    )

    folium.TileLayer(
        tiles="https://mt1.google.com/vt/lyrs=y&x={x}&y={y}&z={z}",
        attr="Google",
        name="Satellite View",
        overlay=False,
        control=True,
    ).add_to(m_gis)

    folium.TileLayer(
        "OpenStreetMap",
        name="Street View",
    ).add_to(m_gis)

    folium.LayerControl().add_to(m_gis)
    Fullscreen(position="topright").add_to(m_gis)

    for _, row in df_mapped.iterrows():
        lat = float(row["Latitude"])
        lon = float(row["Longitude"])

        try:
            area = float(row["Plot Area (Ha)"])
        except (TypeError, ValueError):
            area = 0.0

        if not math.isfinite(area) or area < 0:
            area = 0.0

        # This is only a visual approximation, not a legal boundary.
        offset = (
            0.0005 * math.sqrt(area)
            if area > 0
            else 0.0005
        )

        # Prevent absurdly large demo polygons.
        offset = min(offset, 0.05)

        polygon_coords = [
            [lat - offset, lon - offset],
            [lat + offset, lon - offset],
            [lat + offset, lon + offset],
            [lat - offset, lon + offset],
        ]

        popup_html = (
            f"<b>{t('Khasra No:')}</b> "
            f"{row['Khasra / Survey No']}<br>"
            f"<b>{t('Owner:')}</b> "
            f"{row['Landowner']}<br>"
            f"<b>{t('Area:')}</b> "
            f"{area:.2f} Ha<br>"
            f"<b>{t('Village:')}</b> "
            f"{row['Village']}<br>"
            f"<small>{t('Approximate visualization only')}</small>"
        )

        folium.Polygon(
            locations=polygon_coords,
            color="#2563eb",
            weight=2,
            fill=True,
            fill_color="#3b82f6",
            fill_opacity=0.35,
            popup=folium.Popup(
                popup_html,
                max_width=300,
            ),
        ).add_to(m_gis)

        folium.Marker(
            location=[lat, lon],
            icon=folium.Icon(
                color="red",
                icon="info-sign",
            ),
            popup=folium.Popup(
                popup_html,
                max_width=300,
            ),
        ).add_to(m_gis)

    st_folium(
        m_gis,
        width=1200,
        height=600,
        key="gis_viewer_map",
    )


